input.content:
$seat: 2rem;
$aisle: 4rem;
$label: 1.5rem;

$colors: (
  available: #2e7d32,
  selected: #f9a825,
  unavailable: #c62828,
  accessible: #1565c0,
);

.page {
  max-width: 70rem;
  margin: 0 auto;
  padding: 2rem;
}

.auditorium-wrap {
  width: fit-content;
  margin: 0 auto;
}

.seat-limit-info {
  text-align: center;
  margin-bottom: 1rem;
}

.screen {
  text-align: center;
  background: #333;
  color: #fff;
  letter-spacing: 0.3rem;
  padding: 0.5rem;
  margin-bottom: 1rem;
  border-radius: 0.25rem;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 0.25rem;
}

.seat-row {
  display: grid;
  grid-template-columns: $label repeat(4, $seat) $aisle repeat(16, $seat) $aisle repeat(4, $seat) $label;
  align-items: center;
  column-gap: 2px;
}

.row-label {
  text-align: center;
  font-size: 0.8rem;
  font-weight: 600;
}

.aisle {
  height: $seat;
}

.seat,
.couch {
  height: $seat;
  border: none;
  border-radius: 3px;
  cursor: pointer;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 0.65rem;
  padding: 0;
  color: #fff;

  &:focus-visible {
    outline: 2px solid #000;
    outline-offset: 1px;
  }

  &[data-state='unavailable'] {
    cursor: not-allowed;
  }
}

@each $state, $color in $colors {
  .seat[data-state='#{$state}'],
  .couch[data-state='#{$state}'],
  .swatch[data-state='#{$state}'] {
    background-color: $color;
  }
}

.legend {
  display: flex;
  gap: 1.5rem;
  justify-content: center;
  margin-top: 1.5rem;
}

.legend-item {
  display: flex;
  align-items: center;
  gap: 0.4rem;
}

.swatch {
  width: 1rem;
  height: 1rem;
  border-radius: 3px;
  display: inline-block;
}

.selected-seats {
  margin: 1.5rem auto 0;
  max-width: 24rem;

  p {
    margin: 0.2rem 0;
  }
}

.actions {
  display: flex;
  justify-content: center;
  gap: 1rem;
  margin-top: 1.5rem;
}

